// Open-Meteo API 응답을 Notion 속성 구조에 맞게 가공
const weather = $input.first().json.current;
const units = $input.first().json.current_units;

// WMO Weather Code 매핑
const weatherCodeMap = {
  0: 'Clear sky',
  1: 'Mainly clear',
  2: 'Partly cloudy',
  3: 'Overcast',
  45: 'Fog',
  48: 'Depositing rime fog',
  51: 'Light drizzle',
  53: 'Moderate drizzle',
  55: 'Dense drizzle',
  61: 'Slight rain',
  63: 'Moderate rain',
  65: 'Heavy rain',
  71: 'Slight snow fall',
  73: 'Moderate snow fall',
  75: 'Heavy snow fall',
  80: 'Slight rain showers',
  81: 'Moderate rain showers',
  82: 'Violent rain showers',
  95: 'Thunderstorm',
  96: 'Thunderstorm with slight hail',
  99: 'Thunderstorm with heavy hail'
};

const weatherDescription = weatherCodeMap[weather.weather_code] || 'Unknown';

return [{
  json: {
    properties: {
      '날짜': {
        title: [
          {
            text: {
              content: weather.time
            }
          }
        ]
      },
      '날씨': {
        rich_text: [
          {
            text: {
              content: weatherDescription
            }
          }
        ]
      },
      '기온(°C)': {
        number: weather.temperature_2m
      },
      '습도(%)': {
        number: weather.relative_humidity_2m
      },
      '풍속(km/h)': {
        number: weather.wind_speed_10m
      }
    }
  }
}];
